properties.query:
let workstations =
  DeviceInfo
  | where TimeGenerated > ago(7d)
  | summarize arg_max(TimeGenerated, *) by DeviceId
  | where DeviceType == "Workstation"
  | project DeviceId, DeviceName;
// Fan-out floor. A workstation legitimately making one SSH/RDP connection is
// routine; the hunt is looking for *spread*. Named and tunable so it can be
// raised for a large admin population without editing the query body.
let min_distinct_targets = 3;
DeviceNetworkEvents
| where TimeGenerated > ago(24h)
| where RemotePort in (22, 3389)
// Some connectors classify RFC1918 addresses as "Private" and some leave the
// field empty on internal connections; accept both rather than dropping rows.
| where RemoteIPType == "Private" or isempty(RemoteIPType)
| join kind=inner workstations on DeviceId
| summarize Connections = count(), Targets = make_set(RemoteIP, 25),
            Procs = make_set(InitiatingProcessFileName, 5)
          by DeviceName, AccountName, RemotePort, bin(TimeGenerated, 1h)
| where array_length(Targets) >= min_distinct_targets
